declare module 'gray-matter' {
  interface GrayMatterFile {
    data: { [key: string]: any };
    content: string;
  }

  function matter(input: string): GrayMatterFile;
  export default matter;
}

export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[] | string;
  draft?: boolean;
  template?: string;
  layout?: string;
  [key: string]: unknown;
}

export interface PageData {
  frontmatter: Frontmatter;
  markdown: string;
  html: string;
  sourcePath: string;
  relativePath: string;
  outputPath: string;
  url: string;
  slug: string;
  tags: string[];
  isDraft: boolean;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  devMode: boolean;
  port: number;
  includeDrafts: boolean;
  siteTitle: string;
  siteUrl: string;
}

export interface TemplateContext {
  page: PageData;
  pages: PageData[];
  site: SiteConfig;
  body?: string;
  content?: string;
  [key: string]: unknown;
}

import { Command } from 'commander';
import { SiteConfig } from './types';

export function parseArgs(argv: string[]): SiteConfig {
  const program = new Command();

  program
    .name('ssg')
    .description('Static site generator with Markdown, Handlebars, and live reload')
    .requiredOption('-s, --source <dir>', 'Source directory of Markdown files')
    .requiredOption('-t, --templates <dir>', 'Template directory of Handlebars files')
    .requiredOption('-o, --output <dir>', 'Output directory for generated HTML')
    .option('-d, --dev', 'Run in dev mode with live reload server')
    .option('-p, --port <port>', 'Dev server port', '3000')
    .option('--drafts', 'Include draft pages')
    .option('--title <title>', 'Site title', 'My Site')
    .option('--url <url>', 'Site URL for RSS feed', 'http://localhost:3000')
    .exitOverride();

  try {
    program.parse(argv);
  } catch (err: any) {
    if (err.code === 'commander.missingRequiredOption') {
      throw new Error(`Missing required option: ${err.message}`);
    }
    throw err;
  }

  const opts = program.opts<{
    source: string;
    templates: string;
    output: string;
    dev?: boolean;
    port: string;
    drafts?: boolean;
    title: string;
    url: string;
  }>();

  return {
    sourceDir: opts.source,
    templateDir: opts.templates,
    outputDir: opts.output,
    devMode: opts.dev || false,
    port: parseInt(opts.port, 10),
    includeDrafts: opts.drafts || false,
    siteTitle: opts.title,
    siteUrl: opts.url,
  };
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import hljs from 'highlight.js';
import { Frontmatter, PageData } from './types';

const renderer = new marked.Renderer();
renderer.code = (code: string, language: string | undefined, _isEscaped: boolean): string => {
  const lang = language && hljs.getLanguage(language) ? language : 'plaintext';
  const highlighted = hljs.highlight(code, { language: lang }).value;
  return `<pre><code class="hljs language-${lang}">${highlighted}</code></pre>\n`;
};

marked.setOptions({ renderer });

export function parseMarkdownFile(filePath: string, sourceDir: string): PageData {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);

  const frontmatter: Frontmatter = {
    title: data.title || path.basename(filePath, '.md'),
    date: data.date ? String(data.date) : undefined,
    tags: normalizeTags(data.tags),
    draft: data.draft === true || data.draft === 'true',
    template: data.template,
    layout: data.layout,
  };

  for (const key of Object.keys(data)) {
    if (!['title', 'date', 'tags', 'draft', 'template', 'layout'].includes(key)) {
      (frontmatter as Record<string, unknown>)[key] = data[key];
    }
  }

  const html = marked.parse(content) as string;

  const relativePath = path.relative(sourceDir, filePath);
  const parsed = path.parse(relativePath);
  const slug = path.join(parsed.dir, parsed.name).replace(/\\/g, '/');
  const url = '/' + slug.replace(/\/index$/, '');
  const outputPath = path.join(slug, 'index.html');

  return {
    frontmatter,
    markdown: content,
    html,
    sourcePath: filePath,
    relativePath,
    outputPath,
    url,
    slug,
    tags: (frontmatter.tags as string[]) || [],
    isDraft: frontmatter.draft === true,
  };
}

function normalizeTags(tags: unknown): string[] {
  if (!tags) return [];
  if (Array.isArray(tags)) return tags.map((t) => String(t));
  if (typeof tags === 'string') {
    return tags.split(',').map((t) => t.trim()).filter(Boolean);
  }
  return [];
}

import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { SiteConfig, PageData, TemplateContext } from './types';

export function setupHandlebars(config: SiteConfig): void {
  registerPartials(config.templateDir);
  registerHelpers();
}

function registerPartials(templateDir: string): void {
  const partialsDir = path.join(templateDir, 'partials');
  if (!fs.existsSync(partialsDir)) return;

  for (const file of fs.readdirSync(partialsDir)) {
    if (file.endsWith('.hbs') || file.endsWith('.handlebars')) {
      const name = path.basename(file, path.extname(file));
      const content = fs.readFileSync(path.join(partialsDir, file), 'utf-8');
      Handlebars.registerPartial(name, content);
    }
  }
}

function registerHelpers(): void {
  Handlebars.registerHelper('formatDate', function (date: string) {
    if (!date) return '';
    const d = new Date(date);
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  });

  Handlebars.registerHelper('eq', function (a: unknown, b: unknown) {
    return a === b;
  });
}

const FALLBACK_TEMPLATE = `<!DOCTYPE html>
<html>
<head><title>{{page.frontmatter.title}}</title></head>
<body>{{{content}}}</body>
</html>`;

export function renderPage(
  page: PageData,
  allPages: PageData[],
  config: SiteConfig
): string {
  const context: TemplateContext = {
    page,
    pages: allPages.filter((p) => !p.isDraft || config.includeDrafts),
    site: config,
  };

  const templateName = page.frontmatter.template || 'default';
  const templatePath = path.join(config.templateDir, `${templateName}.hbs`);

  let templateContent: string;
  if (fs.existsSync(templatePath)) {
    templateContent = fs.readFileSync(templatePath, 'utf-8');
  } else if (templateName === 'default') {
    templateContent = FALLBACK_TEMPLATE;
  } else {
    throw new Error(`Template not found: ${templateName}.hbs`);
  }

  const template = Handlebars.compile(templateContent);
  let html = template({ ...context, content: page.html });

  if (page.frontmatter.layout) {
    const layoutPath = path.join(
      config.templateDir,
      'layouts',
      `${page.frontmatter.layout}.hbs`
    );
    if (fs.existsSync(layoutPath)) {
      const layoutContent = fs.readFileSync(layoutPath, 'utf-8');
      const layoutTemplate = Handlebars.compile(layoutContent);
      html = layoutTemplate({
        ...context,
        content: page.html,
        body: html,
      });
    }
  }

  return html;
}

export function renderTagPage(
  tag: string,
  taggedPages: PageData[],
  allPages: PageData[],
  config: SiteConfig
): string {
  const templatePath = path.join(config.templateDir, 'tag.hbs');

  let templateContent: string;
  if (fs.existsSync(templatePath)) {
    templateContent = fs.readFileSync(templatePath, 'utf-8');
  } else {
    templateContent = `<!DOCTYPE html>
<html>
<head><title>Tag: {{tag}} - {{site.siteTitle}}</title></head>
<body>
  <h1>Posts tagged: {{tag}}</h1>
  <ul>
    {{#each taggedPages}}
    <li><a href="{{this.url}}">{{this.frontmatter.title}}</a></li>
    {{/each}}
  </ul>
</body>
</html>`;
  }

  const template = Handlebars.compile(templateContent);

  const context = {
    page: {
      frontmatter: { title: `Tag: ${tag}`, tags: [], draft: false },
      html: '',
      url: `/tags/${tag}/`,
      slug: `tags/${tag}`,
      tags: [] as string[],
      isDraft: false,
    } as PageData,
    pages: allPages.filter((p) => !p.isDraft || config.includeDrafts),
    taggedPages,
    tag,
    site: config,
  };

  return template(context);
}

import fs from 'fs';
import path from 'path';
import { SiteConfig, PageData } from './types';
import { parseMarkdownFile } from './parser';
import { renderPage, renderTagPage, setupHandlebars } from './renderer';

export async function generateSite(config: SiteConfig): Promise<PageData[]> {
  setupHandlebars(config);

  const pages = collectPages(config);

  const publishablePages = config.includeDrafts
    ? pages
    : pages.filter((p) => !p.isDraft);

  if (fs.existsSync(config.outputDir)) {
    fs.rmSync(config.outputDir, { recursive: true });
  }
  fs.mkdirSync(config.outputDir, { recursive: true });

  for (const page of publishablePages) {
    const html = renderPage(page, pages, config);
    const outFile = path.join(config.outputDir, page.outputPath);
    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, html);
  }

  generateTagPages(pages, config);
  generateRssFeed(publishablePages, config);
  copyStaticAssets(config);

  return pages;
}

function collectPages(config: SiteConfig): PageData[] {
  const pages: PageData[] = [];
  walkDir(config.sourceDir, (filePath) => {
    if (filePath.endsWith('.md')) {
      pages.push(parseMarkdownFile(filePath, config.sourceDir));
    }
  });
  return pages;
}

export function walkDir(
  dir: string,
  callback: (filePath: string) => void
): void {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walkDir(fullPath, callback);
    } else {
      callback(fullPath);
    }
  }
}

function generateTagPages(pages: PageData[], config: SiteConfig): void {
  const tagMap = new Map<string, PageData[]>();

  for (const page of pages) {
    if (page.isDraft && !config.includeDrafts) continue;
    for (const tag of page.tags) {
      if (!tagMap.has(tag)) tagMap.set(tag, []);
      tagMap.get(tag)!.push(page);
    }
  }

  for (const [tag, taggedPages] of tagMap) {
    const html = renderTagPage(tag, taggedPages, pages, config);
    const outDir = path.join(config.outputDir, 'tags', tag);
    fs.mkdirSync(outDir, { recursive: true });
    fs.writeFileSync(path.join(outDir, 'index.html'), html);
  }
}

function generateRssFeed(pages: PageData[], config: SiteConfig): void {
  const posts = pages
    .filter((p) => !p.isDraft && p.frontmatter.date)
    .sort(
      (a, b) =>
        new Date(b.frontmatter.date!).getTime() -
        new Date(a.frontmatter.date!).getTime()
    );

  let xml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(config.siteUrl)}</link>
    <description>${escapeXml(config.siteTitle)} RSS Feed</description>
    <atom:link href="${escapeXml(config.siteUrl)}/feed.xml" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
`;

  for (const page of posts) {
    const url = `${config.siteUrl}${page.url}`;
    xml += `    <item>
      <title>${escapeXml(page.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid>${escapeXml(url)}</guid>
      <pubDate>${new Date(page.frontmatter.date!).toUTCString()}</pubDate>
      <description>${escapeXml(page.html.slice(0, 500))}</description>
    </item>
`;
  }

  xml += `  </channel>
</rss>`;

  fs.writeFileSync(path.join(config.outputDir, 'feed.xml'), xml);
}

function escapeXml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function copyStaticAssets(config: SiteConfig): void {
  walkDir(config.sourceDir, (filePath) => {
    if (!filePath.endsWith('.md')) {
      const relativePath = path.relative(config.sourceDir, filePath);
      const outPath = path.join(config.outputDir, relativePath);
      fs.mkdirSync(path.dirname(outPath), { recursive: true });
      fs.copyFileSync(filePath, outPath);
    }
  });
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { SiteConfig } from './types';
import { generateSite } from './generator';

const RELOAD_WS_PATH = '/__reload';

const RELOAD_SCRIPT_INJECT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '${RELOAD_WS_PATH}');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
  ws.onclose = function() {
    console.log('Live reload disconnected, retrying...');
    setTimeout(function() {
      window.location.reload();
    }, 2000);
  };
})();
</script>`;

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const mimes: Record<string, string> = {
    '.html': 'text/html',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.svg': 'image/svg+xml',
    '.xml': 'application/xml',
    '.txt': 'text/plain',
  };
  return mimes[ext] || 'application/octet-stream';
}

export async function startDevServer(config: SiteConfig): Promise<void> {
  await generateSite(config);

  injectReloadScript(config);

  const clients = new Set<WebSocket>();

  const server = http.createServer((req, res) => {
    const url = req.url || '/';
    let filePath = path.join(config.outputDir, url === '/' ? 'index.html' : url);

    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
      res.writeHead(200, { 'Content-Type': getMimeType(filePath) });
      res.end(fs.readFileSync(filePath));
      return;
    }

    const indexPath = path.join(filePath, 'index.html');
    if (fs.existsSync(indexPath)) {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(fs.readFileSync(indexPath));
      return;
    }

    res.writeHead(404);
    res.end('Not found');
  });

  const wss = new WebSocketServer({ noServer: true });

  server.on('upgrade', (request, socket, head) => {
    if (request.url === RELOAD_WS_PATH) {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit('connection', ws, request);
      });
    } else {
      socket.destroy();
    }
  });

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  const reloadClients = () => {
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  };

  const watcher = chokidar.watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });

  let rebuildTimeout: NodeJS.Timeout | null = null;
  watcher.on('all', async (event, filePath) => {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(async () => {
      try {
        await generateSite(config);
        injectReloadScript(config);
        reloadClients();
        console.log(`[${new Date().toISOString()}] Rebuilt after ${event}: ${filePath}`);
      } catch (err) {
        console.error('Rebuild error:', err);
      }
    }, 100);
  });

  server.listen(config.port, () => {
    console.log(`Dev server running at http://localhost:${config.port}`);
  });
}

function injectReloadScript(config: SiteConfig): void {
  function walk(dir: string) {
    if (!fs.existsSync(dir)) return;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.name.endsWith('.html')) {
        let html = fs.readFileSync(fullPath, 'utf-8');
        if (!html.includes(RELOAD_WS_PATH)) {
          html = html.replace('</body>', RELOAD_SCRIPT_INJECT + '</body>');
          fs.writeFileSync(fullPath, html);
        }
      }
    }
  }
  walk(config.outputDir);
}

#!/usr/bin/env node
import { parseArgs } from './cli';
import { generateSite } from './generator';
import { startDevServer } from './dev-server';

async function main() {
  const config = parseArgs(process.argv);

  if (config.devMode) {
    await startDevServer(config);
  } else {
    const pages = await generateSite(config);
    console.log(`Generated ${pages.length} pages in ${config.outputDir}`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { describe, it, expect } from 'vitest';
import { parseMarkdownFile } from '../src/parser';
import fs from 'fs';
import path from 'path';
import os from 'os';

function createTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
}

function createFile(dir: string, name: string, content: string): string {
  const filePath = path.join(dir, name);
  const dirPath = path.dirname(filePath);
  fs.mkdirSync(dirPath, { recursive: true });
  fs.writeFileSync(filePath, content);
  return filePath;
}

describe('frontmatter parsing', () => {
  it('parses title from frontmatter', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: My Test Page
---
Content here.`);

    const page = parseMarkdownFile(file, dir);
    expect(page.frontmatter.title).toBe('My Test Page');
    expect(page.html).toContain('Content here.');
    fs.rmSync(dir, { recursive: true });
  });

  it('falls back to filename when no title in frontmatter', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'my-post.md', `---
tags: [misc]
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.frontmatter.title).toBe('my-post');
    fs.rmSync(dir, { recursive: true });
  });

  it('parses date from frontmatter', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
date: 2024-01-15
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.frontmatter.date).toBe('2024-01-15');
    fs.rmSync(dir, { recursive: true });
  });

  it('parses tags as YAML array', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
tags: [javascript, "typescript"]
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.tags).toEqual(['javascript', 'typescript']);
    fs.rmSync(dir, { recursive: true });
  });

  it('parses tags as comma-separated string', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
tags: javascript, typescript, css
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.tags).toEqual(['javascript', 'typescript', 'css']);
    fs.rmSync(dir, { recursive: true });
  });

  it('returns empty array for missing tags', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.tags).toEqual([]);
    fs.rmSync(dir, { recursive: true });
  });

  it('detects draft: true', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
draft: true
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.isDraft).toBe(true);
    fs.rmSync(dir, { recursive: true });
  });

  it('draft defaults to false', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.isDraft).toBe(false);
    fs.rmSync(dir, { recursive: true });
  });

  it('draft: false is recognized', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
draft: false
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.isDraft).toBe(false);
    fs.rmSync(dir, { recursive: true });
  });

  it('generates correct URL slug for root file', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.url).toBe('/test');
    fs.rmSync(dir, { recursive: true });
  });

  it('generates clean URL for index page', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'index.md', `---
title: Home
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.url).toBe('/');
    fs.rmSync(dir, { recursive: true });
  });

  it('generates nested URL for subdirectories', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'posts/hello-world.md', `---
title: Hello
---
Content`);

    const page = parseMarkdownFile(file, dir);
    expect(page.url).toBe('/posts/hello-world');
    fs.rmSync(dir, { recursive: true });
  });

  it('parses markdown to HTML', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
---
# Heading

Paragraph with **bold** text.`);

    const page = parseMarkdownFile(file, dir);
    expect(page.html).toContain('<h1');
    expect(page.html).toContain('<strong>bold</strong>');
    fs.rmSync(dir, { recursive: true });
  });

  it('applies syntax highlighting to code blocks', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'test.md', `---
title: Test
---
\`\`\`javascript
const x = 1;
\`\`\``);

    const page = parseMarkdownFile(file, dir);
    expect(page.html).toContain('hljs');
    expect(page.html).toContain('language-javascript');
    fs.rmSync(dir, { recursive: true });
  });

  it('handles no frontmatter at all', () => {
    const dir = createTempDir();
    const file = createFile(dir, 'plain.md', 'Just some content.');

    const page = parseMarkdownFile(file, dir);
    expect(page.frontmatter.title).toBe('plain');
    expect(page.isDraft).toBe(false);
    expect(page.tags).toEqual([]);
    expect(page.html).toContain('Just some content.');
    fs.rmSync(dir, { recursive: true });
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { renderPage, renderTagPage, setupHandlebars } from '../src/renderer';
import { SiteConfig, PageData } from '../src/types';
import path from 'path';
import fs from 'fs';
import os from 'os';

const fixturesDir = path.join(__dirname, '..', 'test-fixtures');
const templateDir = path.join(fixturesDir, 'templates');

const baseConfig: SiteConfig = {
  sourceDir: path.join(fixturesDir, 'source'),
  templateDir,
  outputDir: fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-output-')),
  devMode: false,
  port: 3000,
  includeDrafts: false,
  siteTitle: 'Test Site',
  siteUrl: 'http://localhost:3000',
};

const samplePage: PageData = {
  frontmatter: {
    title: 'Hello World',
    date: '2024-01-15',
    tags: ['javascript', 'tutorial'],
    draft: false,
    template: 'post',
    layout: 'base',
  },
  html: '<p>Hello World content</p>',
  markdown: 'Hello World content',
  sourcePath: '/test/source/posts/hello-world.md',
  relativePath: 'posts/hello-world.md',
  outputPath: 'posts/hello-world/index.html',
  url: '/posts/hello-world',
  slug: 'posts/hello-world',
  tags: ['javascript', 'tutorial'],
  isDraft: false,
};

describe('template rendering', () => {
  beforeAll(() => {
    setupHandlebars(baseConfig);
  });

  it('renders a page with a named template', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('<article');
    expect(html).toContain('Hello World');
  });

  it('renders page content as HTML', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('<p>Hello World content</p>');
  });

  it('renders a page without layout when none specified', () => {
    const noLayoutPage: PageData = {
      ...samplePage,
      frontmatter: { title: 'No Layout', template: 'default' },
    };
    const html = renderPage(noLayoutPage, [noLayoutPage], baseConfig);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>No Layout</title>');
    expect(html).not.toContain('<header>');
    expect(html).not.toContain('<footer>');
  });

  it('renders a page with layout', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Hello World - Test Site</title>');
  });

  it('renders partials inside layout', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('<header>');
    expect(html).toContain('<nav>');
    expect(html).toContain('Home');
    expect(html).toContain('About');
    expect(html).toContain('<footer>');
    expect(html).toContain('&copy; 2024');
  });

  it('renders tags as links', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('/tags/javascript/');
    expect(html).toContain('/tags/tutorial/');
  });

  it('renders tag page with tagged posts', () => {
    const html = renderTagPage('javascript', [samplePage], [samplePage], baseConfig);
    expect(html).toContain('Posts tagged: javascript');
    expect(html).toContain('Hello World');
    expect(html).toContain('/posts/hello-world');
  });

  it('formats dates with formatDate helper', () => {
    const html = renderPage(samplePage, [samplePage], baseConfig);
    expect(html).toContain('January 15, 2024');
  });

  it('throws for nonexistent template', () => {
    const badPage: PageData = {
      ...samplePage,
      frontmatter: { title: 'Bad', template: 'nonexistent' },
    };
    expect(() => renderPage(badPage, [badPage], baseConfig)).toThrow(
      'Template not found'
    );
  });

  it('uses fallback template when default.hbs does not exist', () => {
    const configNoDefault: SiteConfig = {
      ...baseConfig,
      templateDir: '/nonexistent/dir',
    };
    const page: PageData = {
      ...samplePage,
      frontmatter: { title: 'Fallback', template: 'default' },
    };
    const html = renderPage(page, [page], configNoDefault);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Fallback</title>');
  });

  it('skips layout silently when layout file does not exist', () => {
    const page: PageData = {
      ...samplePage,
      frontmatter: {
        ...samplePage.frontmatter,
        layout: 'nonexistent_layout',
      },
    };
    const html = renderPage(page, [page], baseConfig);
    expect(html).toContain('<article');
  });

  it('excludes draft pages from pages list', () => {
    const draftPage: PageData = {
      ...samplePage,
      frontmatter: { ...samplePage.frontmatter, title: 'Draft', draft: true },
      isDraft: true,
    };
    const html = renderPage(samplePage, [samplePage, draftPage], baseConfig);
    expect(html).not.toContain('Draft');
  });

  afterAll(() => {
    fs.rmSync(baseConfig.outputDir, { recursive: true, force: true });
  });
});

import { describe, it, expect } from 'vitest';
import { parseArgs } from '../src/cli';

function args(...flags: string[]): string[] {
  return ['node', 'ssg', '-s', 'source', '-t', 'templates', '-o', 'output', ...flags];
}

describe('CLI flag behavior', () => {
  it('parses required short options', () => {
    const config = parseArgs(['node', 'ssg', '-s', 'src', '-t', 'tmpl', '-o', 'dist']);
    expect(config.sourceDir).toBe('src');
    expect(config.templateDir).toBe('tmpl');
    expect(config.outputDir).toBe('dist');
  });

  it('parses required long options', () => {
    const config = parseArgs([
      'node', 'ssg',
      '--source', 'content',
      '--templates', 'theme',
      '--output', 'public',
    ]);
    expect(config.sourceDir).toBe('content');
    expect(config.templateDir).toBe('theme');
    expect(config.outputDir).toBe('public');
  });

  it('dev mode defaults to false', () => {
    const config = parseArgs(args());
    expect(config.devMode).toBe(false);
  });

  it('enables dev mode with -d', () => {
    const config = parseArgs(args('-d'));
    expect(config.devMode).toBe(true);
  });

  it('enables dev mode with --dev', () => {
    const config = parseArgs(args('--dev'));
    expect(config.devMode).toBe(true);
  });

  it('default port is 3000', () => {
    const config = parseArgs(args());
    expect(config.port).toBe(3000);
  });

  it('parses port with -p', () => {
    const config = parseArgs(args('-p', '8080'));
    expect(config.port).toBe(8080);
  });

  it('parses port with --port', () => {
    const config = parseArgs(args('--port', '4000'));
    expect(config.port).toBe(4000);
  });

  it('includeDrafts defaults to false', () => {
    const config = parseArgs(args());
    expect(config.includeDrafts).toBe(false);
  });

  it('sets includeDrafts with --drafts', () => {
    const config = parseArgs(args('--drafts'));
    expect(config.includeDrafts).toBe(true);
  });

  it('default site title is "My Site"', () => {
    const config = parseArgs(args());
    expect(config.siteTitle).toBe('My Site');
  });

  it('parses site title with --title', () => {
    const config = parseArgs(args('--title', 'My Blog'));
    expect(config.siteTitle).toBe('My Blog');
  });

  it('default site URL is http://localhost:3000', () => {
    const config = parseArgs(args());
    expect(config.siteUrl).toBe('http://localhost:3000');
  });

  it('parses site URL with --url', () => {
    const config = parseArgs(args('--url', 'https://example.com'));
    expect(config.siteUrl).toBe('https://example.com');
  });

  it('throws on missing required source option', () => {
    expect(() =>
      parseArgs(['node', 'ssg', '-t', 't', '-o', 'o'])
    ).toThrow('Missing required option');
  });

  it('throws on missing required templates option', () => {
    expect(() =>
      parseArgs(['node', 'ssg', '-s', 's', '-o', 'o'])
    ).toThrow('Missing required option');
  });

  it('throws on missing required output option', () => {
    expect(() =>
      parseArgs(['node', 'ssg', '-s', 's', '-t', 't'])
    ).toThrow('Missing required option');
  });
});

